const docs: Record<string,{title:string;intro:string;sections:[string,string,string][]}> = {
  "getting-started":{title:"Getting Started",intro:"A practical path from the tenant model to your first verification run.",sections:[["Prerequisites","Know your tenant boundary.","Before integrating, decide what constitutes a tenant, how identity maps to a tenant and which resources must never cross that boundary."],["Step 1 — Map the request","Find every tenant-aware path.","Identify synchronous API calls, background jobs and internal services that can read or mutate tenant data."],["Step 2 — Introduce tenant context","Make the decision explicit.","Carry tenant scope through the request path and ensure downstream code cannot silently fall back to an unscoped operation."],["Step 3 — Enforce","Place the boundary before protected data.","Use Proxima enforcement and database controls to reject requests whose tenant scope does not match the protected resource."],["Step 4 — Verify","Test both success and failure.","Run same-tenant, cross-tenant and invalid-context scenarios. A useful verification suite proves the negative cases, not only the happy path."],["Step 5 — Review evidence","Understand the result.","Inspect verification and audit evidence before treating the integration as complete."]] },
  "core-concepts":{title:"Core Concepts",intro:"The vocabulary behind the Proxima architecture.",sections:[["Organization","The customer boundary for control-plane configuration.","An organization groups the resources, users, billing context and operational configuration belonging to a customer."],["Tenant","The data-isolation boundary inside an application.","A tenant is the scope whose data must remain isolated from other tenants."],["Tenant context","The requested tenant scope carried through a request.","Context allows the enforcement layer to compare the requested tenant with the protected resource."],["Policy","The rules that determine what is permitted.","Policies provide the explicit decision model used by the enforcement system."],["Verification","A test of the isolation property.","Verification deliberately exercises expected allow and block paths."],["Evidence","The inspectable result.","Evidence gives engineers and security teams a concrete record of what was checked and what happened."]] },
  "api-reference":{title:"API Reference",intro:"Reference material for integrating with the Proxima control plane and protected request model.",sections:[["Authentication","Establish the calling identity.","Use the authentication mechanism supported by your deployed environment. Keep credentials out of browser bundles and source control."],["Tenant context","Pass the intended scope.","Tenant-aware operations must carry enough context for the enforcement boundary to evaluate the request."],["Verification","Run and inspect verification.","Verification operations should report the scenarios tested and the resulting decisions."],["Errors","Diagnose without leaking data.","Clients should distinguish authentication, context, policy and verification failures while avoiding sensitive payload disclosure."]] },
  security:{title:"Security",intro:"How the Proxima model addresses tenant isolation failures.",sections:[["Threat model","Assume the application can make mistakes.","The architecture considers wrong tenant scope, expired context, authorization mistakes and bypassed application checks."],["Defense in depth","Use more than one control.","Application enforcement and database isolation should reinforce one another."],["Verification","Test the dangerous paths.","A secure design is more credible when it can demonstrate that cross-tenant attempts are actually blocked."],["Evidence","Keep the trail.","Record the outcome so a security review can examine what was verified instead of relying on a verbal claim."]] },
  operations:{title:"Operations",intro:"Operate Proxima as infrastructure rather than a hidden library feature.",sections:[["Environments","Separate operational contexts.","Keep development, staging and production configuration distinguishable and avoid accidentally using production credentials during local development."],["Deployments","Know what changed.","Connect deployments to verification so an infrastructure change can be followed by an explicit isolation check."],["Nodes","Understand execution state.","Track the Proxima nodes or execution components that participate in enforcement and verification."],["Incidents","Preserve evidence.","When a failure occurs, capture the verification result, affected environment and relevant events before changing state. "]] },
  troubleshooting:{title:"Troubleshooting",intro:"Diagnose common integration and isolation failures systematically.",sections:[["Cross-tenant request blocked","This is often the expected security result.","Confirm the request's intended tenant and the protected resource. If they differ, the block demonstrates the boundary is working."],["Expired context","The request can no longer prove valid tenant scope.","Refresh or regenerate context using the supported authentication flow, then retry and confirm the resulting decision."],["Verification failure","A test did not produce the expected decision.","Start with the failing scenario, inspect context and policy inputs, then examine evidence to determine where the decision diverged."],["Database enforcement failure","The application and database disagree.","Inspect database policy configuration and the tenant value reaching the database. Do not disable enforcement to make a request succeed."]] },
};
